'use client'

import { useRef, type ReactNode } from 'react'
import { useGSAP } from '@/lib/hooks/useGSAP'
import { prefersReducedMotion, useReducedMotion } from './useReducedMotion'

export type MarqueeProps = {
  children: ReactNode
  className?: string
  itemClassName?: string
  speed?: number
  direction?: 'left' | 'right'
  gap?: number
  pauseOnHover?: boolean
  ariaLabel?: string
}

export function Marquee({
  children,
  className,
  itemClassName,
  speed = 60,
  direction = 'left',
  gap = 32,
  pauseOnHover = true,
  ariaLabel,
}: MarqueeProps) {
  const root = useRef<HTMLDivElement>(null)
  const track = useRef<HTMLDivElement>(null)
  const firstSet = useRef<HTMLDivElement>(null)
  const reduced = useReducedMotion()

  useGSAP(
    ({ gsap }) => {
      const container = root.current
      const rail = track.current
      const set = firstSet.current
      if (!container || !rail || !set || reduced || prefersReducedMotion()) return

      let tween: gsap.core.Tween | undefined
      const build = (): void => {
        tween?.kill()
        gsap.set(rail, { x: 0 })

        const distance = set.getBoundingClientRect().width + gap
        if (distance <= 0) return

        tween = gsap.fromTo(
          rail,
          { x: direction === 'left' ? 0 : -distance },
          {
            x: direction === 'left' ? -distance : 0,
            duration: distance / Math.max(speed, 1),
            ease: 'none',
            repeat: -1,
          },
        )
      }

      const pause = (): void => {
        tween?.pause()
      }
      const resume = (): void => {
        tween?.resume()
      }
      const resizeObserver =
        typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(build)
      resizeObserver?.observe(set)
      window.addEventListener('resize', build)
      build()

      if (pauseOnHover) {
        container.addEventListener('pointerenter', pause)
        container.addEventListener('pointerleave', resume)
        container.addEventListener('focusin', pause)
        container.addEventListener('focusout', resume)
      }

      return () => {
        resizeObserver?.disconnect()
        window.removeEventListener('resize', build)
        container.removeEventListener('pointerenter', pause)
        container.removeEventListener('pointerleave', resume)
        container.removeEventListener('focusin', pause)
        container.removeEventListener('focusout', resume)
        tween?.kill()
      }
    },
    [direction, gap, pauseOnHover, reduced, speed],
    root,
  )

  const groupStyle = {
    display: 'flex',
    flex: 'none',
    gap,
  } as const

  return (
    <div ref={root} className={className} aria-label={ariaLabel} style={{ overflow: 'hidden' }}>
      <div
        ref={track}
        style={{ display: 'flex', gap, width: 'max-content', willChange: 'transform' }}
      >
        <div ref={firstSet} className={itemClassName} style={groupStyle}>
          {children}
        </div>
        <div
          ref={(node) => node?.setAttribute('inert', '')}
          aria-hidden="true"
          className={itemClassName}
          style={groupStyle}
        >
          {children}
        </div>
      </div>
    </div>
  )
}

'use client'

import type { ReactNode } from 'react'

import { Marquee } from './Marquee'
import { cn } from '@/lib/utils'

export type SocialChannelItem = {
  name: string
  icon?: ReactNode
  color?: string
}

export type SocialChannelMarqueeProps = {
  eyebrow?: string
  title: string
  channels: readonly SocialChannelItem[]
  speed?: number
  className?: string
}

export function SocialChannelMarquee({
  eyebrow,
  title,
  channels,
  speed = 55,
  className,
}: SocialChannelMarqueeProps) {
  return (
    <section className={cn('overflow-hidden bg-[#1b1b1b] py-16 text-white md:py-20', className)}>
      <div className="container text-center">
        {eyebrow ? (
          <p className="text-xs font-bold uppercase tracking-[0.2em] text-[#f4c95d]">{eyebrow}</p>
        ) : null}
        <h2 className="mx-auto mt-4 max-w-3xl text-3xl font-bold tracking-tight md:text-5xl">
          {title}
        </h2>
      </div>

      <Marquee
        speed={speed}
        gap={16}
        ariaLabel="Canais e integrações compatíveis"
        className="mt-12"
        itemClassName="items-center"
      >
        {channels.map((channel) => (
          <div
            key={channel.name}
            className="flex min-w-[180px] items-center gap-3 rounded-2xl border border-white/15 bg-white/5 px-5 py-4 transition hover:border-white/35 hover:bg-white/10"
          >
            <span
              className="flex h-10 w-10 items-center justify-center rounded-xl text-lg font-black text-white"
              style={{ backgroundColor: channel.color ?? '#2f6fed' }}
              aria-hidden
            >
              {channel.icon ?? channel.name.slice(0, 1)}
            </span>
            <span className="font-semibold">{channel.name}</span>
          </div>
        ))}
      </Marquee>
    </section>
  )
}

'use client'

import { useEffect, useState } from 'react'

const QUERY = '(prefers-reduced-motion: reduce)'

export function prefersReducedMotion(): boolean {
  return typeof window !== 'undefined' && window.matchMedia(QUERY).matches
}

export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const media = window.matchMedia(QUERY)
    const update = (): void => setReduced(media.matches)

    update()
    media.addEventListener('change', update)
    return () => media.removeEventListener('change', update)
  }, [])

  return reduced
}

'use client'

import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { useEffect, type DependencyList, type RefObject } from 'react'

let registered = false

function ensureGsapPlugins(): void {
  if (typeof window === 'undefined' || registered) return
  gsap.registerPlugin(ScrollTrigger)
  registered = true
}

export type GSAPTools = {
  gsap: typeof gsap
  ScrollTrigger: typeof ScrollTrigger
}

export type GSAPCallback = (tools: GSAPTools) => void | (() => void)

export function useGSAP(
  callback: GSAPCallback,
  deps: DependencyList = [],
  scope?: RefObject<Element | null>,
): void {
  useEffect(() => {
    if (typeof window === 'undefined') return

    ensureGsapPlugins()

    let dispose: void | (() => void)
    const context = gsap.context(() => {
      dispose = callback({ gsap, ScrollTrigger })
    }, scope?.current ?? undefined)

    return () => {
      dispose?.()
      context.revert()
    }

    // Dependencies are deliberately controlled by each animation consumer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
